def body(pattern):
    m=re.search(pattern,text);assert m,pattern;at=m.end();depth=1
    while at<len(text):
        if text.startswith('//',at):end=text.find('\n',at);at=len(text)if end<0 else end+1;continue
        if text.startswith('/*',at):end=text.find('*/',at+2);assert end>=0;at=end+2;continue
        if text[at]in('"',"'"):
            quote=text[at];at+=1
            while at<len(text):
                if text[at]=='\\':at+=2;continue
                if text[at]==quote:at+=1;break
                at+=1
            continue
        if text[at]=='{':depth+=1
        elif text[at]=='}':
            depth-=1
            if not depth:return text[m.start():at+1]
        at+=1
    raise AssertionError(pattern)
